template:
% 参数由系统自动注入；不规则四边形：C 点坐标直接由参数给定（折叠问题原图）
% 视觉归一化：把最长边缩放到 6 个坐标单位，线宽字体不缩放
\pgfmathsetmacro{\Dx}{\ad*cos(\anglea)}
\pgfmathsetmacro{\Dy}{\ad*sin(\anglea)}
\pgfmathsetmacro{\bc}{sqrt((\cx-\ab)^2 + \cy*\cy)}
\pgfmathsetmacro{\cd}{sqrt((\cx-\Dx)^2 + (\cy-\Dy)^2)}
\pgfmathsetmacro{\figscale}{6 / max(\ab, \ad, \bc, \cd)}
\begin{tikzpicture}[scale=\figscale, every node/.style={font=\small, fill=none, inner sep=1.5pt}]
  \coordinate (A) at (0,0);
  \coordinate (B) at (\ab,0);
  \coordinate (D) at (\Dx,\Dy);
  \coordinate (C) at (\cx,\cy);
  \draw[thick] (A) -- (B) -- (C) -- (D) -- cycle;
  % 对角线 AC
  \ifnum\showdiagac>0
    \draw[thick] (A) -- (C);
  \fi
  % 对角线 BD
  \ifnum\showdiagbd>0
    \draw[thick] (B) -- (D);
  \fi
  % 顶点标签
  \node[below left=3pt] at (A) {$A$};
  \node[below right=3pt] at (B) {$B$};
  \node[above right=3pt] at (C) {$C$};
  \node[above left=3pt] at (D) {$D$};
\end{tikzpicture}
